CREATE TABLE IF NOT EXISTS infrastructure_resources (id INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, customer_id INTEGER NOT NULL, provider TEXT NOT NULL DEFAULT 'hostinger', provider_resource_id TEXT NOT NULL DEFAULT '', type TEXT NOT NULL, name TEXT NOT NULL, domain TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'unknown', plan_name TEXT NOT NULL DEFAULT '', expires_at TEXT NOT NULL DEFAULT '', auto_renew INTEGER NOT NULL DEFAULT 0, region TEXT NOT NULL DEFAULT '', ip_address TEXT NOT NULL DEFAULT '', last_synced_at TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(provider,provider_resource_id,customer_id));
CREATE INDEX IF NOT EXISTS idx_infrastructure_customer_type ON infrastructure_resources(customer_id,type);
CREATE TABLE IF NOT EXISTS uptime_monitors (id INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, customer_id INTEGER NOT NULL, resource_id INTEGER NOT NULL DEFAULT 0, domain TEXT NOT NULL, check_url TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending', last_http_status INTEGER NOT NULL DEFAULT 0, last_response_ms INTEGER NOT NULL DEFAULT 0, ssl_expires_at TEXT NOT NULL DEFAULT '', last_checked_at TEXT NOT NULL DEFAULT '', consecutive_failures INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(customer_id,domain));
CREATE INDEX IF NOT EXISTS idx_uptime_monitor_status ON uptime_monitors(status,last_checked_at);
CREATE TABLE IF NOT EXISTS infrastructure_incidents (id INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, customer_id INTEGER NOT NULL, monitor_id INTEGER NOT NULL DEFAULT 0, type TEXT NOT NULL, severity TEXT NOT NULL DEFAULT 'warning', title TEXT NOT NULL, safe_summary TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'open', opened_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, resolved_at TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_infrastructure_incident_customer ON infrastructure_incidents(customer_id,status,opened_at);
